"use strict";(globalThis.webpackChunksagrest_docs=globalThis.webpackChunksagrest_docs||[]).push([[8130],{7735(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"novita-in-arrivo-2026","metadata":{"permalink":"/blog/novita-in-arrivo-2026","editUrl":"https://github.com/sagrest-soft/sagrest-docs/tree/main/blog/2026-06-15-novit\xe0-in-arrivo.md","source":"@site/blog/2026-06-15-novit\xe0-in-arrivo.md","title":"Novit\xe0 in arrivo su Sagrest!","description":"L\'inizio della stagione delle sagre 2026 segna un nuovo capitolo per Sagrest, che a breve verr\xe0 aggiornato con l\'obiettivo di rendere l\'organizzazione degli eventi ancora pi\xf9 semplice, veloce ed efficiente.","date":"2026-06-15T00:00:00.000Z","tags":[{"inline":false,"label":"Informazioni","permalink":"/blog/tags/info","description":"Articoli con informazioni generiche su Sagrest"}],"readingTime":0.96,"hasTruncateMarker":true,"authors":[{"name":"Matteo Gheza","title":"Sviluppatore Back-End Sagrest","url":"https://matteogheza.it","socials":{"github":"https://github.com/matteogheza"},"imageURL":"https://github.com/matteogheza.png","key":"matteogheza","page":null}],"frontMatter":{"slug":"novita-in-arrivo-2026","title":"Novit\xe0 in arrivo su Sagrest!","authors":["matteogheza"],"tags":["info"]},"unlisted":false,"nextItem":{"title":"Benvenuti nel blog di Sagrest","permalink":"/blog/benvenuti"}},"content":"L\'inizio della stagione delle sagre 2026 segna un nuovo capitolo per Sagrest, che a breve verr\xe0 aggiornato con l\'obiettivo di rendere l\'organizzazione degli eventi ancora pi\xf9 semplice, veloce ed efficiente.\\n\\n\x3c!-- truncate --\x3e\\n\\nTra le funzionalit\xe0 in arrivo troviamo una migliore integrazione con il sistema di pagamento SumUp, inclusa la possibilit\xe0 di monitorare lo stato dei lettori di carte direttamente da Sagrest.\\n\\nStiamo inoltre lavorando all\'introduzione di strumenti basati sull\'intelligenza artificiale per velocizzare l\'importazione di prodotti e menu, riducendo il tempo necessario alla configurazione iniziale della manifestazione. Una delle novit\xe0 pi\xf9 importanti in questo ambito sar\xe0 il chatbot integrato, che permetter\xe0 di aggiungere o modificare dati tramite semplici richieste in linguaggio naturale, consultare rapidamente i report di vendita e ottenere risposte immediate sulla documentazione del software.\\n\\n\xc8 in arrivo anche una nuova interfaccia web di gestione, completamente rinnovata per offrire prestazioni migliori, maggiore rapidit\xe0 e un\'esperienza d\'uso pi\xf9 intuitiva.\\n\\nInfine, stiamo introducendo diversi miglioramenti all\'interfaccia degli ordini online per rendere l\'esperienza di acquisto pi\xf9 fluida e piacevole per i visitatori.\\n\\nNon vediamo l\'ora di condividere con voi le prossime novit\xe0 e di accompagnarvi in un\'altra fantastica stagione di feste, tradizioni e comunit\xe0. Restate sintonizzati! \ud83d\ude80"},{"id":"benvenuti","metadata":{"permalink":"/blog/benvenuti","editUrl":"https://github.com/sagrest-soft/sagrest-docs/tree/main/blog/2024-09-06-benvenuti.md","source":"@site/blog/2024-09-06-benvenuti.md","title":"Benvenuti nel blog di Sagrest","description":"Ecco a voi un nuovo spazio dedicato a tutti gli utenti e curiosi di Sagrest, il programma di gestione delle sagre che semplifica l\'organizzazione e la pianificazione delle feste di paese!","date":"2024-09-06T00:00:00.000Z","tags":[{"inline":false,"label":"Informazioni","permalink":"/blog/tags/info","description":"Articoli con informazioni generiche su Sagrest"}],"readingTime":0.78,"hasTruncateMarker":true,"authors":[{"name":"Matteo Gheza","title":"Sviluppatore Back-End Sagrest","url":"https://matteogheza.it","socials":{"github":"https://github.com/matteogheza"},"imageURL":"https://github.com/matteogheza.png","key":"matteogheza","page":null}],"frontMatter":{"slug":"benvenuti","title":"Benvenuti nel blog di Sagrest","authors":["matteogheza"],"tags":["info"]},"unlisted":false,"prevItem":{"title":"Novit\xe0 in arrivo su Sagrest!","permalink":"/blog/novita-in-arrivo-2026"}},"content":"Ecco a voi un nuovo spazio dedicato a tutti gli utenti e curiosi di Sagrest, il programma di gestione delle sagre che semplifica l\'organizzazione e la pianificazione delle feste di paese!\\n\\n\x3c!-- truncate --\x3e\\n\\nIn questo blog troverete tutte le novit\xe0 e gli aggiornamenti sul nostro software, inclusi i dettagli sulle future versioni. Condivideremo informazioni sulle nuove funzionalit\xe0, ed eventuali breaking changes che potrebbero richiedere attenzione da parte degli utenti.\\n\\nInoltre, pubblicheremo casi d\'uso reali di Sagrest applicati a varie sagre e feste popolari, per mostrarvi come la nostra piattaforma possa essere personalizzata e utilizzata con successo nelle pi\xf9 diverse situazioni. Ogni sagra ha le proprie tradizioni e peculiarit\xe0, e Sagrest \xe8 qui per aiutarvi a gestire il tutto con facilit\xe0 e precisione.\\n\\nRestate sintonizzati per rimanere sempre aggiornati sui miglioramenti e le novit\xe0 di Sagrest. Siamo entusiasti di condividere con voi il nostro percorso verso un modo pi\xf9 smart e organizzato di vivere le feste di paese!"}]}}')}}]);